    def __init__(self):
        self.stack1 = []
        self.stack2 = []

    def enqueue(self, item):
        self.stack1.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.stack2.pop()

    def is_full(self):
        return len(self.stack1) == len(self.stack2)

    def is_empty(self):
        return len(self.stack1) == 0

    def peek(self):
        if not self.is_full():
            return self.stack1[-1]

    def size(self):
        return len(self.stack1)
